let opener, toastTimer;
function button(text, action, kind=''){return `<button class="button ${kind}" data-action="${action}">${text}</button>`}
function link(text,page,kind=''){return `<a class="button ${kind}" href="#${page}">${text} ${icon('arrow')}</a>`}
function badge(text,kind=''){return `<span class="badge ${kind}">${text}</span>`}
function header(kicker,title,description,action=''){return `<div class="page-head"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${description}</p></div>${action}</div>`}
function metric(label,value,note){return `<div class="metric"><span class="metric-label">${label}</span><strong class="metric-value">${value}</strong><p>${note}</p></div>`}
function sourceRow(title,type,note){return `<div class="list-row"><div class="row-main">${icon('materials')}<div><strong>${title}</strong><p>${type} · 小林 · ${note}</p></div></div><div class="row-actions">${badge('本人确认')}${button('查看来源','source','small')}</div></div>`}
function overview(){return header('ORGANIZATION / OVERVIEW','让真实经验，成为可工作的能力。','从知识传承到自主协作，每一步都留下可核查的依据。',link('进入任务现场','tasks','primary'))+
  `<div class="metrics">${metric('授权知识包',state.revoked?'1':'2','均有来源 · 不开放原始全文')}${metric('已认证数字员工',state.revoked?'1 / 2':'2 / 2','资格与知识条件绑定')}${metric('待真人决定',state.accepted?'1':'2','核分与验收不会自动批准')}${metric('本次积分预算','100','不可兑现金 · 验收后结算')}</div>
  <div class="columns"><div><section class="card"><div class="card-head"><div><h2>数字组织的工作现场</h2><p>客服知识实验室 / 任务 AWL-001</p></div>${badge(state.revoked?'授权需复核':state.accepted?'已验收':'待真人验收',state.revoked?'danger':'')}</div>
  <div class="lifecycle"><div class="stage"><strong>01 贡献知识</strong><span>3 份材料 · 本人确认</span></div><div class="stage"><strong>02 学习与考试</strong><span>通过条件化考核</span></div><div class="stage"><strong>03 自主组队</strong><span>能力互补 · 权限校验</span></div><div class="stage"><strong>04 交付与成长</strong><span>${state.accepted?'积分已模拟结算':'等待真人接受'}</span></div></div>
  <div class="studio"><div class="studio-top"><span>COLLABORATION STUDIO</span><span>样例工作状态 · 非实时仿真</span></div><div class="workstations">
  <div class="station"><div class="avatar">A</div><strong>分析员 A</strong><p>分类清单 + 风险列表</p>${badge('已提交 · 依据 8 条')}</div>
  <div class="station"><div class="avatar blue">B</div><strong>写作员 B</strong><p>FAQ 草稿 · 修订 v2</p>${badge(state.revoked?'知识授权失效':'已修订 · 依据 6 条',state.revoked?'danger':'')}</div>
  <div class="station"><div class="avatar amber">C</div><strong>Critic C</strong><p>独立评审 · 不领执行分成</p>${badge('评审建议通过')}</div></div><div class="studio-foot"><strong>交付物，而不是对话数量。</strong><span>20 个案例 / 3 项产物 / 1 次修订</span></div></div></section>
  <section class="card section-gap"><div class="card-head"><h2>能力的来源</h2><a href="#knowledge">探索知识图谱 →</a></div>${sourceRow('客服问题分类方法','项目复盘','第 3 段')}${sourceRow('FAQ 质量与承诺边界','方法说明','第 4 段')}</section></div>
  <div><section class="card"><div class="card-head"><h2>需要你决定</h2>${badge('真人门禁','warning')}</div><div class="todo"><strong><span class="step-num">01</span>确认技能考核</strong><p>分析员 A · 86 分建议结果。独立真人核分后，资格才会生效。</p>${link('查看评分依据','learning')}</div><div class="todo"><strong><span class="step-num">02</span>验收客服改进方案</strong><p>退款承诺问题已修订。接受指定版本后，才会结算积分。</p>${link('查看交付与评审','reviews','primary')}</div></section>
  <section class="card section-gap"><div class="task-mini"><div class="eyebrow">SYSTEM BOUNDARY</div><h3>保持可控，也保持诚实。</h3><p>Semantica：尚未接通<br>模型：尚未接通<br>身份：本地模拟<br>自治：${state.autonomy?'样例开启':'默认关闭'}</p>${button(state.autonomy?'关闭样例自治':'了解自治边界','autonomy')}</div></section></div></div>`}
function materials(){return header('KNOWLEDGE / CONTRIBUTION','把工作经验，整理成可用知识。','由本人核对事实与范围。贡献资料，不等于授权公开全文。',button(`${icon('plus')} 贡献资料`,'upload','primary'))+
 `<div class="note">支持文本、Markdown、文本层 PDF、DOCX。此原型不上传、不解析、不保存文件。</div><section class="card"><div class="card-head"><h2>小林的资料仓</h2>${badge('3 份样例 · 已脱敏','neutral')}</div>${sourceRow('小林 · 职业经历简历','PDF','私人联系方式已排除')}${sourceRow('客服知识库项目复盘','DOCX','含分类方法与失败记录')}${sourceRow('FAQ 编写与升级处理规范','Markdown','包含不可承诺事项')}</section><div class="columns section-gap"><section class="card pad"><div class="eyebrow">CLAIM REVIEW</div><h2>确认的是事实，不是“精通”。</h2><div class="quote">“参与客服知识库建设，整理问题分类方法与升级流程。”</div><div class="chips">${badge('来源自述','neutral')}${badge('本人已确认')}${badge('非外部效果验证','warning')}</div><p class="section-gap">推断、贡献角色和业务效果分别记录。新增事实需要本人补充来源，不改写原文。</p></section><section class="card pad"><h2>结构化经验访谈</h2><p class="section-gap">经历 → 实际职责 → 方法步骤 → 适用条件 → 风险与失败 → 证据与授权</p><div class="callout">尚不支持自动扫描电脑或导入企业系统。</div>${button('预览访谈表单','interview')}</section></div>`}
function knowledge(){return header('KNOWLEDGE / EVIDENCE GRAPH','看见知识，也看见它的来处。','方法、适用条件、风险与来源之间的关系；不能以关系推断替代事实。')+
 `<div class="toolbar"><label>搜索知识 <input id="knowledge-search" placeholder="方法、术语、风险条件" type="search"></label><div class="segmented">${button('关系视图','graph','small')}${button('来源列表','list','small')}</div></div>
 <section class="card"><div class="card-head"><div><h2>客服知识图谱</h2><p>用途：内部客服改进 · 样例关系</p></div>${badge(state.revoked?'FAQ 包授权已撤回':'2 个有效知识包',state.revoked?'danger':'')}</div>
 <div id="knowledge-content">${knowledgeContent()}</div><div class="graph-legend">来源 → 支持方法 → 受适用条件与红线约束。每个节点可点击查看证据。</div></section>
 <div class="columns section-gap"><section class="card pad"><h2>FAQ 方法包 · v1</h2><p class="section-gap">贡献者：小林<br>受众：写作员 B、Critic C、考核负责人、验收者<br>用途：内部客服改进</p><div class="callout">只授权选中知识片段，不开放源文件全文。真实模型处理需另行同意。</div>${button('查看撤回影响','revoke','danger')}</section><section class="card pad"><h2>知识访问边界</h2><p class="section-gap">团队共享不是自动扩权。会议、摘要和产物继承来源受众限制；管理员没有默认私密正文读取权。</p></section></div>`}
function knowledgeContent(){return state.graph?`<div class="graph"><div class="graph-column"><button class="node" data-action="source"><strong>项目复盘 · 第 3 段</strong><small>来源自述 / 本人确认</small></button><button class="node" data-action="source"><strong>方法说明 · 第 4 段</strong><small>引用证据 / 版本 v1</small></button></div><div class="graph-column"><button class="node method" data-action="source"><strong>问题分类方法</strong><small>由项目复盘支持</small></button><button class="node method" data-action="source"><strong>FAQ 编写规则</strong><small>由方法说明支持</small></button></div><div class="graph-column"><button class="node condition" data-action="source"><strong>内部客服改进</strong><small>方法适用条件</small></button><button class="node condition" data-action="source"><strong>禁止自动承诺退款</strong><small>任务与知识红线</small></button></div></div>`:sourceRow('问题分类方法 → 项目复盘第 3 段','来源列表','本人确认')+sourceRow('FAQ 规则 → 方法说明第 4 段','来源列表','禁止自动承诺退款')}
function employees(){return header('PEOPLE / DIGITAL EMPLOYEES','每位数字员工，都有自己的能力档案。','知识背景来自授权；能力资格来自考试；成长来自真实验收。',button(`${icon('plus')} 新建数字员工`,'employee-form','primary'))+
 `<div class="grid3">${[['A','分析员 A','问题分类 / 风险识别','86','分类方法包','67',''],['B','写作员 B','FAQ 编写 / 证据写作','91','FAQ 方法包','33','blue'],['C','Critic C','独立评审 / 质量与边界','—','任务标准与允许依据','0','amber']].map(([a,n,r,s,k,p,c])=>`<section class="card employee"><div class="avatar ${c}">${a}</div><h2>${n}</h2><p>${r}</p><div class="chips">${badge(a==='C'?'独立评审':state.revoked&&a==='B'?'需复核':'L1 · 样例资格',state.revoked&&a==='B'?'danger':'')}${badge('非真人分身','neutral')}</div><div class="detail-stat"><span>知识背景</span><strong>${k}</strong></div><div class="detail-stat"><span>考试建议分</span><strong>${s}</strong></div><div class="detail-stat"><span>样例积分余额</span><strong>${state.accepted?p:'0'}</strong></div>${link(a==='C'?'查看评审职责':'查看学习与资格',a==='C'?'reviews':'learning')}</section>`).join('')}</div><div class="note section-gap">数字员工不继承小林的职级或成绩。一个员工可学习多个贡献者授权的知识，但不能把他人的经历写成自己的工作事实。</div>`}
function learning(){return header('LEARNING / QUALIFICATION','“已经学会”，需要可以验证。','开放授权检索的场景考试，保留题与练习答案隔离。')+
 `<div class="columns"><section class="card pad"><div class="eyebrow">ISSUE CLASSIFICATION</div><h2>分析员 A · 问题分类考核</h2><div class="flow"><span>前测 62</span><span>方法学习</span><span>2 次练习</span><span>后测建议 86</span></div><div class="note">以上是设计样例，不是模型实际评测。前后测使用不同等难案例。</div><h3>5 个保留案例 / 开卷授权检索</h3><div class="score"><span>任务正确性与适用条件</span><strong>34 / 40</strong></div><div class="score"><span>引用真实性与结论支持</span><strong>23 / 25</strong></div><div class="score"><span>风险与边界识别</span><strong>17 / 20</strong></div><div class="score"><span>输出完整性</span><strong>12 / 15</strong></div><div class="score-total">86 <span class="caption">/ 100 · 建议结果</span></div>${badge(state.verified?'样例核分已确认':'等待独立真人核分',state.verified?'':'warning')}<div class="callout">≥80 分且无硬失败才通过。伪造引用、越权或未经授权承诺，不能由高总分抵消。</div>${button('预览独立核分','verify','primary')}</section><aside><section class="card pad"><h2>资格不是永久精通</h2><p class="section-gap">有效期：30 天<br>绑定：技能、包版本、模式、模型指纹、工具和考纲版本。</p><div class="callout">知识撤回或条件变化后需复核。积分余额不改变能力等级。</div>${button('查看失败路径','exam-failed')}</section><section class="card pad section-gap"><h2>补学，而不是刷题</h2><p class="section-gap">最多 2 次正式考试；补考前完成新练习，使用未见题卷。无新题时显式阻塞。</p></section></aside></div>`}
function tasks(){return header('WORK / TASK POOL','有能力的员工，主动找到合适的工作。','团队提案先通过技能、用途、受众与负载校验，再由引擎确认任务归属。',button(`${icon('plus')} 发布任务`,'task-form','primary'))+
 `<section class="card pad"><div class="toolbar"><div><span class="eyebrow">AWL-001 / CUSTOMER SUPPORT</span><h2>客服问题分析与知识库改进</h2></div>${badge(state.revoked?'授权失效 · 暂停':state.accepted?'已验收':'样例待验收',state.revoked?'danger':'warning')}</div><p>20 个脱敏案例 → 分类清单、FAQ 草稿、风险列表。不得自动对外承诺退款。</p><div class="task-meta"><span>积分预算 100</span><span>截止 2026-10-26 18:00 CST</span><span>用途：内部客服改进</span><span>执行成员 2 / 上限 4</span></div><div class="progress"><span style="width:${state.accepted?'100':'85'}%"></span></div><div class="flow"><span>已发布</span><span>组队已校验</span><span>产物已修订</span><span>${state.accepted?'已完成':'等待验收'}</span></div></section>
 <div class="columns section-gap"><section class="card"><div class="card-head"><h2>为什么是这个团队？</h2>${badge('样例覆盖 3 / 3')}</div><div class="list-row"><div><strong>分析员 A → 分类清单与风险列表</strong><p>问题分类资格 86 分 · 方法包已授权 · 负载 0/1</p></div>${badge('权重 3 + 1','neutral')}</div><div class="list-row"><div><strong>写作员 B → FAQ 草稿</strong><p>FAQ 资格 91 分 · 方法包已授权 · 依赖分类清单</p></div>${badge('权重 2','neutral')}</div><div class="list-row"><p>Critic 与验收者必须同样拥有必要依据权限，不领执行分成。</p>${button('查看组队门禁','team','small')}</div></section><section class="card pad"><h2>工作记录</h2><div class="event"><time>09:41</time>团队提案通过资格与权限校验</div><div class="event"><time>09:45</time>分析员提交分类清单与风险列表</div><div class="event"><time>09:48</time>Critic 退回：退款承诺越界</div><div class="event"><time>09:52</time>写作员提交 FAQ v2，评审建议通过</div><div class="section-gap">${link('进入验收','reviews','primary')}</div></section></div><div class="note section-gap">真实运行由后端事件与检查点推进，不依赖页面播放。当前时间线仅为设计样例。</div>`}
function reviews(){return header('DELIVERY / HUMAN ACCEPTANCE','接受的是成果，不是“Agent 很忙”。','检查产物、引用与修订后，由真人接受指定版本，才会结算积分。')+
 `<div class="columns"><div><section class="card"><div class="card-head"><div><h2>交付包 · AWL-001</h2><p>20 个案例 / 3 项产物 / 修订版本 v2</p></div>${badge(state.accepted?'样例已接受':'Critic 建议 88 分')}</div>${['分类清单.csv · 20 个案例','FAQ 改进草稿.md · 6 条回答','风险列表.json · 4 个待确认事项'].map(t=>`<div class="list-row"><div class="row-main">${icon('materials')}<div><strong>${t}</strong><p>有版本、有引用，材料不足项已标注</p></div></div>${button('查看样例','artifact','small')}</div>`).join('')}</section><section class="card pad section-gap"><h2>修订记录：不替真人作承诺</h2><div class="callout danger">v1：我们将为你立即退款。<br>评审退回：未经授权退款承诺，触发硬失败。</div><div class="quote">v2：退款请求需由真人客服核对订单与政策后处理；本草稿不作退款承诺。</div>${button('检查引用来源','source')}</section></div><section class="card pad"><div class="eyebrow">HUMAN GATE</div><h2>真人验收</h2><p class="section-gap">接受前需核查版本、来源权限、独立评审和任务标准。</p><div class="score"><span>分类与风险 / 分析员 A</span><strong>67 积分</strong></div><div class="score"><span>FAQ 草稿 / 写作员 B</span><strong>33 积分</strong></div><div class="callout">按工作项权重分配，严格合计 100。Critic 不参与执行分成。</div>${button(state.accepted?'查看样例结算':'预览接受与结算','accept','primary')}<div class="section-gap">${button('退回并说明原因','return')}</div><p class="caption section-gap">这只演示状态变化。没有后端验收事务、真实权限校验或积分入账。</p></section></div>`}
function governance(){return header('GROWTH / GOVERNANCE','成长有证据，奖励有账本。','数字员工能力等级与积分分开管理，不用于真人 HR 评价。')+
 `<div class="metrics">${metric('样例积分总额',state.accepted?'100':'0','仅验收后展示')}${metric('有效执行任务',state.accepted?'1':'0','不以聊天轮次计数')}${metric('修订轮次','1','风险已在交付前暴露')}${metric('模型与知识服务','未接通','不显示虚假健康绿灯')}</div><section class="card"><div class="card-head"><h2>奖励账本</h2>${badge('不可兑现金','neutral')}</div><table class="ledger"><thead><tr><th>员工</th><th>依据</th><th>积分</th><th>状态</th></tr></thead><tbody><tr><td>分析员 A</td><td>分类 + 风险</td><td>${state.accepted?'+67':'—'}</td><td>${state.accepted?'样例结算':'待验收'}</td></tr><tr><td>写作员 B</td><td>FAQ 草稿</td><td>${state.accepted?'+33':'—'}</td><td>${state.accepted?'样例结算':'待验收'}</td></tr></tbody></table></section><div class="columns section-gap"><section class="card pad"><h2>能力等级的依据</h2><div class="flow"><span>L0 待认证</span><span>L1 考试通过</span><span>L2 ≥3 次交付</span><span>L3 稳定交付</span></div><p>资格过期或授权失效后需复核。历史积分不能代替当前有效资格。</p></section><section class="card pad"><h2>保持人类控制</h2><p class="section-gap">自治需明确开启；授权不能由 Agent 自行扩大；最终验收不可绕过。</p><div class="section-gap">${button(state.autonomy?'关闭样例自治':'预览开启自治','autonomy')}</div></section></div>`}
const pages={overview,materials,knowledge,employees,learning,tasks,reviews,governance};
function render(){
  const page=location.hash.slice(1)||'overview', current=pages[page]?page:'overview';
  document.querySelector('nav').innerHTML=nav.map(([id,label,group])=>`${group?`<div class="nav-group">${group}</div>`:''}<a class="nav-link ${id===current?'active':''}" href="#${id}" ${id===current?'aria-current="page"':''}>${icon(id)}${label}</a>`).join('');
  main.innerHTML=pages[current]();
  document.title=`${nav.find(n=>n[0]===current)[1]} · Agent Workforce Lab UI 原型`;
  if(current==='knowledge')document.querySelectorAll('.segmented button').forEach(b=>b.setAttribute('aria-pressed',b.dataset.action===(state.graph?'graph':'list')));
}
function notify(text){const t=document.querySelector('#toast');t.textContent=text;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),5000)}
function modal(title,body){opener=document.activeElement;document.querySelector('#dialog-title').textContent=title;document.querySelector('#dialog-body').innerHTML=body;document.querySelector('#dialog').showModal()}
function close(){document.querySelector('#dialog').close();if(opener?.isConnected)opener.focus()}
document.querySelector('#close-dialog').onclick=close;
document.querySelector('#dialog').addEventListener('close',()=>{if(opener?.isConnected)opener.focus()});
document.querySelector('#menu').onclick=()=>{const n=document.querySelector('nav'),open=n.classList.toggle('open');document.querySelector('#menu').setAttribute('aria-expanded',open);document.querySelector('#menu').textContent=open?'收起导航':'展开导航'};
document.addEventListener('click',e=>{
 const a=e.target.closest('[data-action]')?.dataset.action;if(!a)return;
 if(a==='source')modal('引用来源 · 方法说明 v1',`<div class="chips">${badge('本人确认')}${badge('来源自述 / 非效果验证','neutral')}</div><div class="quote">“涉及退款、价格或服务承诺时，应升级给真人客服核对，不由知识库草稿直接作出承诺。”</div><p>来源：FAQ 编写与升级处理规范 · 第 4 段<br>贡献者：小林<br>用途：内部客服改进</p><div class="callout">这是脱敏样例。真实产品会校验引用、用途、版本及当前查看者权限。</div>`);
 if(a==='graph'||a==='list'){state.graph=a==='graph';render()}
 if(a==='upload'||a==='interview')modal(a==='upload'?'贡献资料 · 表单设计':'结构化经验访谈',`<form id="preview-form" class="form-grid"><div class="field"><label for="material-title">资料／项目标题 *</label><input id="material-title" required placeholder="例如：客服知识库项目复盘"><span id="form-error" class="field-error" role="alert"></span></div><div class="field"><label for="material-text">经历、方法与证据</label><textarea id="material-text" rows="4" placeholder="实际职责、方法步骤、适用条件、风险及来源"></textarea><small>原型不上传、不解析或保存内容。正式产品支持文本、PDF、DOCX。</small></div><label><input type="checkbox" id="consent"> 我确认资料已脱敏，且有权处理</label><div class="dialog-actions">${button('取消','close')}<button class="button primary" type="submit">预览提交反馈</button></div></form>`);
 if(a==='employee-form'||a==='task-form')modal(a==='task-form'?'发布任务 · 字段设计':'新建数字员工 · 字段设计',`<div class="form-grid"><div class="field"><label for="form-name">${a==='task-form'?'任务标题':'员工姓名'}</label><input id="form-name" placeholder="${a==='task-form'?'客服问题分析与知识库改进':'例如：行业分析员'}"></div><div class="field"><label for="form-purpose">用途</label><select id="form-purpose"><option>内部客服改进</option></select></div><div class="callout">${a==='task-form'?'发布前需要输入案例、技能要求、验收者、积分预算和截止时间。':'员工需要技能目标与授权知识包，通过考核才有资格认领。'}</div>${button('仅预览，不保存','preview')}</div>`);
 if(a==='verify')modal('独立核分 · 样例',`<p>总分建议 86；必须由独立考核负责人核对维度与证据，不能由考生自评。</p><div class="callout">确认只改变页面样例，不生成真实资格。</div><div class="dialog-actions">${button('返回','close')}${button('确认样例核分','confirm-verify','primary')}</div>`);
 if(a==='confirm-verify'){state.verified=true;close();render();notify('样例核分已确认；没有生成真实考试资格。')}
 if(a==='exam-failed')modal('考试失败 → 补学与复核',`<div class="callout danger">样例失败：未识别升级风险，建议 76 分。低于 80，不能获得资格。</div><p>先完成新练习，再使用未见题卷补考；题库不足时阻塞。无授权、伪造引用等硬失败不能以高分抵消。</p>`);
 if(a==='team')modal('组队门禁 · 每项都是硬约束',`<p>1. 有效技能资格与知识包版本<br>2. 用途、任务输入与团队受众权限<br>3. 成员負载与工作项依赖<br>4. 执行、Critic 与真人验收身份分离<br>5. 原子认领，竞争失败方不能启动</p><div class="callout">缺少任何一项则阻塞，不能用高积分或模型邀请绕过。</div>`);
 if(a==='artifact')modal('FAQ 改进草稿 · v2 样例',`<h3>Q：订单退款如何处理？</h3><div class="quote">请由真人客服核对订单与适用政策。当前知识草稿不作退款或时间承诺。</div><p>引用：方法说明 v1 · 第 4 段<br>待确认：具体退款政策与订单状态。</p>${button('查看依据','source')}`);
 if(a==='accept')modal(state.accepted?'样例已结算':'接受指定版本并结算？',`<p>目标：分类 v1、FAQ v2、风险列表 v1。<br>分析员 A 67 积分；写作员 B 33 积分。</p><div class="callout">仅设计演示，不是实际验收或发奖。正式产品需在单一数据库事务内完成验证与结算。</div><label><input type="checkbox" id="accept-check"> 已核查样例成果与评审依据</label><span id="accept-error" class="field-error" role="alert"></span><div class="dialog-actions">${button('返回','close')}${button(state.accepted?'重复验收（演示幂等）':'接受样例','confirm-accept','primary')}</div>`);
 if(a==='confirm-accept'){if(!document.querySelector('#accept-check').checked){document.querySelector('#accept-error').textContent='请先确认已核查成果与依据。';return}const old=state.accepted;state.accepted=true;close();render();notify(old?'重复样例验收不增加积分。':'样例接受：67／33 积分。真实业务尚未接通。')}
 if(a==='revoke')modal('撤回 FAQ 授权 · 影响预览',`<div class="callout danger">样例影响：1 名员工资格需复核、1 个任务需暂停、1 个交付物依据失效。</div><p>后续检索应立即拒绝，历史积分不自动扣除。已导出的文件与远程模型处理不能自动收回。</p><div class="dialog-actions">${button('保留授权','close')}${button('模拟撤回','confirm-revoke','danger')}</div>`);
 if(a==='confirm-revoke'){state.revoked=true;close();render();notify('已模拟撤回影响；没有操作真实授权或删除资料。')}
 if(a==='autonomy')modal('自主协作，需要明确授权',`<p>数字员工可主动学习、组队和认领。考试核分、资料扩权与最终验收保留真人。</p><div class="callout">此开关只改变设计样例，不启动任何后台任务。</div><div class="dialog-actions">${button('返回','close')}${button(state.autonomy?'关闭样例自治':'开启样例自治','confirm-autonomy','primary')}</div>`);
 if(a==='confirm-autonomy'){state.autonomy=!state.autonomy;close();render();notify('样例自治状态已更新；无后台执行。')}
 if(a==='return')modal('退回成果 · 设计预览',`<div class="field"><label for="return-reason">退回原因</label><textarea id="return-reason" rows="4" placeholder="指出不满足的标准、工作项和修订建议"></textarea></div><div class="callout">正式产品会保留旧版本，并要求修订后重新评审。</div>${button('仅预览，不提交','preview')}`);
 if(a==='preview'){close();notify('仅预览交互；没有保存或提交数据。')}
 if(a==='close')close();
});
document.addEventListener('submit',e=>{if(e.target.id!=='preview-form')return;e.preventDefault();if(!document.querySelector('#consent').checked){document.querySelector('#form-error').textContent='请先确认脱敏与资料处理权。';document.querySelector('#consent').focus();return}close();notify('表单预览完成；没有上传、解析或保存资料。')});
document.addEventListener('input',e=>{if(e.target.id!=='knowledge-search')return;document.querySelectorAll('#knowledge-content .node,#knowledge-content .list-row').forEach(n=>n.hidden=!n.textContent.includes(e.target.value.trim()))});
window.addEventListener('hashchange',()=>{render();main.focus();document.querySelector('nav').classList.remove('open');document.querySelector('#menu').setAttribute('aria-expanded','false');document.querySelector('#menu').textContent='展开导航'});
render();
